import {payrollMoney} from './payroll-contract.mjs';
export function createPayrollView({api,h,heading,showPanel,localTime,writable,onEdit}){
 const $=s=>document.querySelector(s);let month='',memberId='',identity,controller,request;const money=payrollMoney;
 const fields=d=>`<dl class="record-facts">${[['基础工资',d.base_cents],['奖金',d.bonus_cents],['补贴',d.allowance_cents],['其他调整',d.adjustment_cents],['草稿合计',d.total_cents]].map(([k,v])=>`<div><dt>${h(k)}</dt><dd>${h(money(v))}</dd></div>`).join('')}</dl>`;
 async function history(m,id,salaries,offset=0){await showPanel(salaries?'基础工资生效历史':'工资草稿历史',async signal=>{const v=await api.payrollHistory(m,id,offset,salaries,signal);return `<div class="dialog-header"><h2>${salaries?'基础工资生效历史':'工资草稿历史'}</h2><button class="icon-button" data-attendance-close aria-label="关闭薪资历史">×</button></div><p class="muted">历史内容保留原值；存在历史草稿不表示当前已核定、已发薪或已记账。</p>${v.rows.map(r=>`<article class="observation"><b>第 ${r.revision} 版 · ${h(localTime(r.created_at))}</b><p>${h(r.actor_name)}</p>${salaries?`<p>${h(r.effective_month)} 生效 · ${h(money(r.amount_cents))}</p>`:fields(r)}<p class="preserve-text">${h(r.note)}</p>${!salaries?`<button class="secondary" data-closure-detail="${h(r.closure_id)}">查看引用的考勤版本</button>`:''}</article>`).join('')||'<p class="muted">暂无记录。</p>'}<div class="pager"><button class="secondary" data-payroll-history="${salaries}" data-month="${h(m)}" data-member="${h(id)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${v.total} 条</span><button class="secondary" data-payroll-history="${salaries}" data-month="${h(m)}" data-member="${h(id)}" data-offset="${offset+50}" ${offset+50>=v.total?'disabled':''}>下一页</button></div>`;});}
 document.addEventListener('click',e=>{const a=e.target.closest('[data-payroll-edit]'),b=e.target.closest('[data-payroll-history]');if(a)onEdit(a.dataset.month,a.dataset.member,a.dataset.payrollEdit==='true');if(b)history(b.dataset.month,b.dataset.member,b.dataset.payrollHistory==='true',Number(b.dataset.offset||0));});
 return {async render(parent,user,back){controller?.abort();controller=new AbortController();const signal=AbortSignal.any([parent,controller.signal]);if(identity!==user.id){identity=user.id;memberId='';month=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date());}
  $('#main').innerHTML=heading('基础工资与工资草稿','仅独立薪资授权人员可查看。草稿引用锁定考勤，不自动发薪或记账。')+`<section class="work-panel module-panel"><div class="module-toolbar"><button class="secondary" id="payroll-back">返回考勤</button><label>月份<input id="payroll-month" type="month" value="${h(month)}" min="1900-01" max="2199-12"></label><label>员工<select id="payroll-member"></select></label></div><div id="payroll-result"></div></section>`;
  const load=async()=>{request?.abort();request=new AbortController();const combined=AbortSignal.any([signal,request.signal]);$('#payroll-result').textContent='正在读取薪资资料…';try{const s=await api.payrollState(month,memberId,combined);if(combined.aborted)return;$('#payroll-member').innerHTML=s.roster.map(m=>`<option value="${h(m.id)}">${h(m.name)}</option>`).join('');if(!s.member){$('#payroll-result').innerHTML='<p>没有关联员工档案。</p>';return;}memberId=s.member.id;$('#payroll-member').value=memberId;const args=`data-month="${h(month)}" data-member="${h(memberId)}"`;
   $('#payroll-result').innerHTML=`<h3>${h(s.member.name)} · ${h(month)}</h3><p>${s.salary?`本月参考基础工资 ${h(money(s.salary.amount_cents))} · ${h(s.salary.effective_month)} 生效，第 ${s.salary.revision} 版`:'本月尚无生效基础工资。'}</p><div class="action-row">${writable?`<button class="secondary" data-payroll-edit="true" ${args}>登记基础工资版本</button>`:''}<button class="secondary" data-payroll-history="true" ${args}>基础工资历史</button></div><p class="planning-rule">${s.attendanceValid?'考勤已锁定且来源一致，可以建立或修订草稿。':'考勤尚未有效锁定或来源已变化，请先返回月度考勤完成核定。'}</p>${s.salaryChanged||s.attendanceChanged?'<p class="planning-rule">原草稿引用已变化，需要重新核对金额并保存新版本。</p>':''}${s.draft?`<h3>当前草稿 · 第 ${s.draft.revision} 版</h3>${fields(s.draft)}<p class="preserve-text">${h(s.draft.note)}</p><button class="secondary" data-closure-detail="${h(s.draft.closure_id)}">查看草稿引用的考勤</button>`:'<p class="muted">尚未建立本月草稿。</p>'}<div class="action-row">${writable?`<button class="primary" data-payroll-edit="false" ${args} ${!s.salary||!s.attendanceValid?'disabled':''}>${s.draft?'核对并修订草稿':'建立本月草稿'}</button>`:''}<button class="secondary" data-payroll-history="false" ${args}>草稿修改历史</button></div><p class="muted">金额均为人工确认；仅相加得到草稿合计。不自动确定扣款、月中折算、绩效或税费，不表示工资已确认或已支付。</p>`;
  }catch(e){if(!combined.aborted&&$('#payroll-result'))$('#payroll-result').textContent=e.message;}};
  $('#payroll-back').onclick=()=>{controller.abort();back();};$('#payroll-month').onchange=()=>{month=$('#payroll-month').value;load();};$('#payroll-member').onchange=()=>{memberId=$('#payroll-member').value;load();};signal.addEventListener('abort',()=>request?.abort(),{once:true});await load();
 }};
}
